param([string]$ProjectRoot=(Split-Path -Parent $PSScriptRoot))
$ErrorActionPreference='Stop'
if([Threading.Thread]::CurrentThread.ApartmentState-ne[Threading.ApartmentState]::STA){throw 'Run with powershell.exe -STA.'}
$halcon='C:\Program Files\MVTec\HALCON-20.11-Progress';$env:PATH=(Join-Path $halcon 'bin\x64-win64')+';'+$env:PATH
Add-Type -AssemblyName PresentationFramework;Add-Type -AssemblyName System.Runtime.Serialization
$exe=Join-Path $ProjectRoot 'bin\x64\Debug\HalconWinFormsDemo.exe';$assembly=[Reflection.Assembly]::LoadFrom($exe)
function Assert([bool]$condition,[string]$message){if(-not$condition){throw $message}}
function Pump([int]$ms){$frame=New-Object Windows.Threading.DispatcherFrame;$timer=New-Object Windows.Threading.DispatcherTimer;$timer.Interval=[TimeSpan]::FromMilliseconds($ms);$timer.Add_Tick({$timer.Stop();$frame.Continue=$false});$timer.Start();[Windows.Threading.Dispatcher]::PushFrame($frame)}
$main=$assembly.GetType('HalconWinFormsDemo.MainWindow',$true);$serviceType=$assembly.GetType('HalconWinFormsDemo.Services.RecipeService',$true);$loggerType=$assembly.GetType('HalconWinFormsDemo.Services.AppLogger',$true);$kindType=$assembly.GetType('HalconWinFormsDemo.Models.VmToolKind',$true);$metadataType=$assembly.GetType('HalconWinFormsDemo.Models.ToolMetadata',$true);$roiType=$assembly.GetType('HalconWinFormsDemo.Models.RoiData',$true);$recipeType=$assembly.GetType('HalconWinFormsDemo.Models.VisionRecipe',$true);$parametersType=$assembly.GetType('HalconWinFormsDemo.Models.VmToolParameterData',$true)
$private=[Reflection.BindingFlags]'Instance,NonPublic';$all=[Reflection.BindingFlags]'Instance,NonPublic,Public';$static=[Reflection.BindingFlags]'Static,Public';$temp=Join-Path([IO.Path]::GetTempPath())('halcon-vm-s62-'+[Guid]::NewGuid().ToString('N'));[IO.Directory]::CreateDirectory($temp)|Out-Null
$service=$serviceType.GetConstructor([Type[]]@([string])).Invoke([object[]]@($temp.ToString()));$logger=$loggerType.GetConstructor([Type[]]@([string])).Invoke([object[]]@($temp.ToString()));$window=$main.GetConstructor($private,$null,[Type[]]@($serviceType,$loggerType),$null).Invoke([object[]]@($service,$logger))
$app=[Windows.Application]::Current;$ownsApp=$null-eq$app;if($ownsApp){$app=New-Object Windows.Application;$app.ShutdownMode=[Windows.ShutdownMode]::OnExplicitShutdown};$window.ShowInTaskbar=$false;$window.Left=-10000;$window.Show();Pump 180
function F([string]$name){$field=$main.GetField($name,$all);if($null-eq$field){return $null};$value=$field.GetValue($window);Write-Output -NoEnumerate $value}
function M([string]$name,[object[]]$parameters=@()){try{$main.GetMethod($name,$private).Invoke($window,$parameters)}catch{$e=$_.Exception;while($e.InnerException){$e=$e.InnerException};throw ($name+': '+$e.Message)}}
function Kind([string]$name){[Enum]::Parse($kindType,$name)}
function Tool([string]$kind,[string]$name){M 'CreateFlowTool' ([object[]]@((Kind $kind),$name,$true,$null))}
function Out($tool,[string]$name){$args=[object[]]@($name,$null);Assert($tool.GetType().GetMethod('TryGetOutputValue').Invoke($tool,$args))('Missing output '+$name);$args[1]}
function RegionStats($region){$a=$null;$r=$null;$c=$null;[HalconDotNet.HOperatorSet]::AreaCenter($region,[ref]$a,[ref]$r,[ref]$c);@([double](($a.ToDArr()|Measure-Object -Sum).Sum),[double]$r.D,[double]$c.D)}
try{
  # A line: the first screen must expose the complete high-capability catalog, not the old eight-tool common subset.
  $expectedToolCount=[Enum]::GetValues($kindType).Count;$catalog=F 'toolCatalog';Assert($catalog.Count-eq$expectedToolCount) 'The toolbox does not contain every implemented tool';Assert((F 'toolCatalogMode')-eq'All') 'The default toolbox mode is not the full categorized catalog';Assert((F 'ToolCatalogList').Items.Count-eq$expectedToolCount) 'The visible default toolbox is still filtered';
  $categories=@($catalog|ForEach-Object{$_.Category}|Sort-Object -Unique);$orders=@($catalog|ForEach-Object{$_.CategoryOrder}|Sort-Object -Unique);Assert($categories.Count-eq9-and$orders.Count-eq9) 'The full toolbox is not split into nine task categories';Assert(($orders-join',')-eq'10,20,30,40,50,60,70,80,90') 'Toolbox category order is not deterministic'
  Assert((F 'ToolCatalogColumn').ActualWidth-ge209) 'The full toolbox is too narrow for continuous use';$catalogCountPattern=([string]$expectedToolCount+'.*9');Assert((F 'ToolCatalogStatusText').Text-match$catalogCountPattern) 'Visible toolbox status count is missing';Assert((F 'ToolCatalogCapabilityText').Text-match$catalogCountPattern) 'Toolbox header is not derived from the live catalog';Assert((F 'DeveloperToolbarPanel').Children.Count-eq7) 'S62 added a permanent top toolbar command';
  $correctionKind=Kind PositionCorrection2D;$inputs=$metadataType.GetMethod('GetInputPorts',$static).Invoke($null,[object[]]@($correctionKind));$outputs=$metadataType.GetMethod('GetOutputPorts',$static).Invoke($null,[object[]]@($correctionKind));foreach($port in @('CurrentRow','CurrentColumn','CurrentAngle')){Assert(($inputs|Where-Object{$_.PortName -eq $port -and $_.DataType -eq 'Number' -and $_.IsOptional}).Count-eq1)('Missing legacy-compatible Number input '+$port)};Assert(($inputs|Where-Object{$_.PortName-eq'Pose2D'-and$_.DataType-eq'Pose2D'}).Count-eq1) 'Missing preferred Pose2D input';foreach($port in @('DeltaRow','DeltaColumn','DeltaAngle','HomMat2D','ResultCode')){Assert(($outputs|Where-Object{$_.PortName -eq $port}).Count-eq1)('Missing correction output '+$port)}

  # B line: run the real HALCON vector_angle_to_rigid tool from three typed upstream values.
  $flow=F 'flowTools';M 'DisposeFlowTools'|Out-Null;$flow.Clear();$row=Tool NumericCalculation 'Current Row';$column=Tool NumericCalculation 'Current Column';$angle=Tool NumericCalculation 'Current Angle';$correction=Tool PositionCorrection2D 'Fixture Position';$blob=Tool Blob 'Following Inspection';$judge=Tool NumericJudge 'Offset Judge';foreach($tool in @($row,$column,$angle,$correction,$blob,$judge)){$flow.Add($tool)}
  $row.SetOutputValue('Number',[double]110);$column.SetOutputValue('Number',[double]220);$angle.SetOutputValue('Number',[double]15);foreach($tool in @($row,$column,$angle)){$tool.ResultCode='OK'}
  $correction.Parameters.PositionCorrectionReferenceRow=100;$correction.Parameters.PositionCorrectionReferenceColumn=200;$correction.Parameters.PositionCorrectionReferenceAngleDegrees=15;$correction.SetInputBinding('CurrentRow',$row.ToolId,'Number');$correction.SetInputBinding('CurrentColumn',$column.ToolId,'Number');$correction.SetInputBinding('CurrentAngle',$angle.ToolId,'Number')
  $record=M 'ExecuteFlowTool' ([object[]]@($correction,'S62 smoke'));Assert($record.ResultCode-eq'OK') '2D correction execution failed';Assert([Math]::Abs([double](Out $correction DeltaRow)-10)-lt1e-9-and[Math]::Abs([double](Out $correction DeltaColumn)-20)-lt1e-9-and[Math]::Abs([double](Out $correction DeltaAngle))-lt1e-9) 'Correction deltas are wrong';Assert((Out $correction HomMat2D)-match',') 'HALCON HomMat2D output is missing'
  $judge.SetInputBinding('Value',$correction.ToolId,'DeltaRow');$judge.InputToolId=$correction.ToolId;$judge.InputPortName='DeltaRow';$judge.NumericLowerLimit=9.9;$judge.NumericUpperLimit=10.1;Assert((M 'ExecuteFlowTool' ([object[]]@($judge,'S62 downstream'))).ResultCode-eq'OK') 'Correction Number output did not drive a downstream judge'

  # Rotation and combined reference/current pose semantics use the matrix produced by the actual tool.
  $correction.Parameters.PositionCorrectionReferenceRow=0;$correction.Parameters.PositionCorrectionReferenceColumn=0;$correction.Parameters.PositionCorrectionReferenceAngleDegrees=0;$row.SetOutputValue('Number',[double]0);$column.SetOutputValue('Number',[double]0);$angle.SetOutputValue('Number',[double]90);M 'ExecuteFlowTool' ([object[]]@($correction,'S62 rotation'))|Out-Null;$matrix=Out $correction HomMat2DHandle;$mappedRow=$null;$mappedColumn=$null;[HalconDotNet.HOperatorSet]::AffineTransPoint2d($matrix.RawData,1.0,0.0,[ref]$mappedRow,[ref]$mappedColumn);Assert([Math]::Abs($mappedRow.D)-lt1e-9-and[Math]::Abs($mappedColumn.D-1)-lt1e-9) 'Positive 90 degree rigid rotation is wrong'
  $correction.Parameters.PositionCorrectionReferenceRow=5;$correction.Parameters.PositionCorrectionReferenceColumn=6;$correction.Parameters.PositionCorrectionReferenceAngleDegrees=10;$row.SetOutputValue('Number',[double]15);$column.SetOutputValue('Number',[double]26);$angle.SetOutputValue('Number',[double]40);M 'ExecuteFlowTool' ([object[]]@($correction,'S62 combined'))|Out-Null;$matrix=Out $correction HomMat2DHandle;$mappedRow=$null;$mappedColumn=$null;[HalconDotNet.HOperatorSet]::AffineTransPoint2d($matrix.RawData,5.0,6.0,[ref]$mappedRow,[ref]$mappedColumn);Assert([Math]::Abs($mappedRow.D-15)-lt1e-9-and[Math]::Abs($mappedColumn.D-26)-lt1e-9-and[Math]::Abs([double](Out $correction DeltaAngle)-30)-lt1e-9) 'Combined translation/rotation did not map the reference pose to the current pose'
  $correction.Parameters.PositionCorrectionReferenceRow=100;$correction.Parameters.PositionCorrectionReferenceColumn=200;$correction.Parameters.PositionCorrectionReferenceAngleDegrees=15;$row.SetOutputValue('Number',[double]110);$column.SetOutputValue('Number',[double]220);$angle.SetOutputValue('Number',[double]15);M 'ExecuteFlowTool' ([object[]]@($correction,'S62 translation restore'))|Out-Null

  # A configured detection ROI and mask both follow the same correction matrix at runtime.
  $blob.Parameters.PositionCorrectionToolId=$correction.ToolId;$detectionGeometry=$roiType.GetMethod('CreateRectangle',$static).Invoke($null,[object[]]@([double]0,[double]0,[double]19,[double]19));$maskGeometry=$roiType.GetMethod('CreateRectangle',$static).Invoke($null,[object[]]@([double]5,[double]5,[double]9,[double]9));$detection=M 'AddRoiLayer' ([object[]]@($detectionGeometry,'Base Detection',$blob));$mask=M 'AddRoiLayer' ([object[]]@($maskGeometry,'Base Mask',$blob));$detectionGeometry.Dispose();$maskGeometry.Dispose();$mask.IsMask=$true
  $region=M 'CreateBoundRoiRegion' ([object[]]@($blob,$true));try{$stats=RegionStats $region;Assert([Math]::Abs($stats[0]-375)-lt.001) 'Corrected detection minus corrected mask area is wrong';Assert([Math]::Abs($stats[1]-19.6666666667)-lt.01-and[Math]::Abs($stats[2]-29.6666666667)-lt.01) 'ROI/mask did not follow Row/Column correction'}finally{$region.Dispose()}
  Assert((M 'GetRoiBindingSummary' ([object[]]@($blob)))-match'Fixture Position') 'ROI summary does not expose its correction source';$blob.ResultCode='OK';$blob.RunStatus='OK';M 'InvalidateDownstreamResults' ([object[]]@($correction,'position changed'))|Out-Null;Assert($blob.RunStatus-ne'OK') 'A correction change did not invalidate the ROI consumer'

  # Source validity and input safety are diagnosed instead of silently using stale geometry.
  $correction.IsEnabled=$false;$message=M 'GetPositionCorrectionBindingConfigurationError' ([object[]]@($blob,$correction.ToolId,$true));Assert($message.Contains($correction.InstanceName)) 'Disabled correction source was accepted';$correction.IsEnabled=$true;$row.SetOutputValue('Number',[double]::NaN);$failed=$false;try{M 'ExecuteFlowTool' ([object[]]@($correction,'S62 NaN'))|Out-Null}catch{$failed=$_.Exception.Message-match'NaN|Infinity'};Assert($failed) 'NaN position input was accepted';$row.SetOutputValue('Number',[double]110);M 'ExecuteFlowTool' ([object[]]@($correction,'S62 recovery'))|Out-Null

  # Recipe JSON, reload, old defaults and clipboard copy preserve stable correction references.
  $blobId=$blob.ToolId;$correctionId=$correction.ToolId;$recipe=M 'CaptureRecipe';$serializer=[Runtime.Serialization.Json.DataContractJsonSerializer]::new($recipeType);$stream=New-Object IO.MemoryStream;try{$serializer.WriteObject($stream,$recipe);$stream.Position=0;$roundtrip=$serializer.ReadObject($stream)}finally{$stream.Dispose()};$saved=$roundtrip.ToolFlow|Where-Object{$_.ToolId -eq $blobId}|Select-Object -First 1;Assert($saved.Parameters.PositionCorrectionToolId-eq$correctionId) 'Recipe JSON lost the ROI correction source';M 'ApplyFlowFromRecipe' ([object[]]@($roundtrip))|Out-Null;$reloaded=$flow|Where-Object{$_.ToolId -eq $blobId}|Select-Object -First 1;Assert($reloaded.Parameters.PositionCorrectionToolId-eq$correctionId) 'Recipe reload lost the correction source';$old=[Activator]::CreateInstance($parametersType);$old.Normalize();Assert([string]::IsNullOrEmpty($old.PositionCorrectionToolId)) 'Old recipes did not default to no correction'
  $correction=$flow|Where-Object{$_.Kind.ToString()-eq'PositionCorrection2D'}|Select-Object -First 1;$blob=$flow|Where-Object{$_.ToolId -eq $blobId}|Select-Object -First 1;(F 'FlowToolList').SelectedItems.Clear();(F 'FlowToolList').SelectedItems.Add($correction);(F 'FlowToolList').SelectedItems.Add($blob);Assert([int](M 'CopySelectedFlowToolsToClipboard')-eq2) 'Correction block copy failed';$before=$flow.Count;Assert([int](M 'PasteFlowToolClipboard' ([object[]]@($flow.Count)))-eq2) 'Correction block paste failed';$newTools=@($flow|Select-Object -Last 2);$newCorrection=$newTools|Where-Object{$_.Kind.ToString()-eq'PositionCorrection2D'}|Select-Object -First 1;$newBlob=$newTools|Where-Object{$_.Kind.ToString()-eq'Blob'}|Select-Object -First 1;Assert($newBlob.Parameters.PositionCorrectionToolId-eq$newCorrection.ToolId) 'Block copy did not remap the stable correction source'
  Write-Output ('S62 full '+$expectedToolCount+'-tool / 9-category default toolbox + HALCON 2D position correction + ROI/mask following + downstream/invalidation/recipe/copy/legacy passed; BSB not implemented by user directive.')
}finally{$main.GetField('recipeCloseConfirmed',$private).SetValue($window,$true);$window.Close();if($ownsApp){$app.Shutdown()};if(Test-Path $temp){Remove-Item -LiteralPath $temp -Recurse -Force}}
